mapper.insert:
INSERT INTO marketing_campaign (
    merchant_id, title, campaign_type, rule_json, start_at, end_at, status, created_at, updated_at
) VALUES (
             #{merchantId}, #{title}, #{campaignType}, #{ruleJson}, #{startAt}, #{endAt}, #{status}, #{createdAt}, #{updatedAt}
         )

mapper.select:
SELECT

FROM marketing_campaign
WHERE status = 1
  AND start_at <= #{now}
  AND end_at >= #{now}

    AND merchant_id = #{merchantId}

ORDER BY created_at DESC, id DESC
LIMIT 100

mapper.update:
UPDATE marketing_campaign
SET status = #{status}
WHERE id = #{id}
